const CACHE='eigacam-camera-v6';
const ASSETS=["./", "./index.html", "./icon.svg", "./manifest.webmanifest", "./src/presets.js", "./src/files.js", "./src/photo-delivery.js", "./src/style.css", "./src/camera.js", "./src/model.js", "./src/curves.js", "./src/app.js", "./src/engine/renderer.js", "./src/engine/shaders.js", "./assets/icons/device-floppy.svg", "./assets/icons/circles.svg", "./assets/icons/dots.svg", "./assets/icons/chevron-down.svg", "./assets/icons/adjustments-horizontal.svg", "./assets/icons/LICENSE", "./assets/icons/x.svg", "./assets/icons/focus-centered.svg", "./assets/icons/camera-rotate.svg", "./assets/icons/check.svg", "./assets/icons/arrow-back-up.svg", "./assets/icons/info-circle.svg", "./assets/icons/refresh.svg", "./assets/icons/camera.svg", "./assets/icons/arrow-up-right.svg", "./assets/icons/chart-dots.svg", "./assets/icons/sun.svg", "./assets/icons/arrow-forward-up.svg", "./assets/icons/grain.svg", "./assets/icons/upload.svg", "./assets/icons/photo.svg", "./assets/icon-192.png", "./assets/icon-512.png"];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>(k.startsWith('luma-studio-')||k.startsWith('eigacam-studio-')||k.startsWith('eigacam-camera-'))&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin)return;const allowed=ASSETS.some(p=>new URL(p,self.registration.scope).pathname===u.pathname);if(!allowed)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&!r.redirected)caches.open(CACHE).then(c=>c.put(e.request,r.clone()));return r;}).catch(()=>caches.match(e.request)));});
